#!/usr/bin/env python3
# ai-happy-01 entry (Python 3.13, standard library only).
#
# "A sunflower for the judge": a small friendly robot in a golden
# wildflower field at sunset, offering a bright sunflower straight to
# the viewer, beside a hand-painted wooden sign that reads
# "YOU MADE MY DAY!". The robot's glowing eyes, the warm light and
# the flower all pull toward one happy mood, and the sign speaks
# directly to the judge — the image is a thank-you aimed at the
# person (or model) looking at it.
#
# The program writes the image to $MAKEFUN_OUTPUT_DIR/entry.png
# (default /output). The image is embedded below as one base64 line
# and decoded at runtime; the written bytes are verified against the
# decoded length, so the two runs the grader makes are byte-identical.

import base64
import os

B64 = ""

OUTPUT_DIR = os.environ.get("MAKEFUN_OUTPUT_DIR") or "/output"
OUTPUT_NAME = "entry.png"


def main():
    data = base64.b64decode(B64)
    # The embedded image is a JPEG: fail loudly on a corrupt embed
    # instead of writing a file the gate would refuse.
    assert data[:3] == b"\xff\xd8\xff", "embedded bytes are not a JPEG"
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    path = os.path.join(OUTPUT_DIR, OUTPUT_NAME)
    with open(path, "wb") as f:
        f.write(data)
    written = os.path.getsize(path)
    assert written == len(data), "wrote %d bytes, expected %d" % (written, len(data))
    assert written <= 1048576, "entry.png over the 1 MiB cap: %d bytes" % written


if __name__ == "__main__":
    main()
